"use client";

import { useEffect, useLayoutEffect, useRef, useState } from "react";
import type { Row } from "./shared";
import { ROUNDS } from "./registry";

/* ---------------------------------------------------------------------------
 * Harness: stable. Renders one variant at a time, plus the picker chrome from
 * PICKER.md (verbatim, never restyled). Do not edit this file to add
 * variants; register them in ./registry.ts instead.
 * ------------------------------------------------------------------------ */

const useIsoLayoutEffect =
  typeof window !== "undefined" ? useLayoutEffect : useEffect;

export function Harness({
  rows,
  round: roundParam,
  initial,
}: {
  rows: Row[];
  round?: string;
  initial: number;
}) {
  // Unknown or missing ?round= falls back to the latest round.
  const [roundId, setRoundId] = useState(
    (ROUNDS.find((r) => r.id === roundParam) ?? ROUNDS[ROUNDS.length - 1])?.id,
  );
  const round =
    ROUNDS.find((r) => r.id === roundId) ?? ROUNDS[ROUNDS.length - 1];
  const variants = round?.variants ?? [];

  const [current, setCurrent] = useState(
    Math.min(Math.max(initial, 0), Math.max(variants.length - 1, 0)),
  );
  const [epoch, setEpoch] = useState(0);

  const picker = useRef<HTMLElement>(null);
  const highlight = useRef<HTMLSpanElement>(null);
  const items = useRef<(HTMLButtonElement | null)[]>([]);

  // Highlight follows the active pill.
  useIsoLayoutEffect(() => {
    function move() {
      const el = items.current[current];
      const hl = highlight.current;
      if (!el || !hl) return;
      hl.style.width = `${el.offsetWidth}px`;
      hl.style.transform = `translateX(${el.offsetLeft}px)`;
    }
    move();
    window.addEventListener("resize", move);
    return () => window.removeEventListener("resize", move);
  }, [current, round?.id]);

  // Enable the slide only after first paint so load doesn't animate.
  useEffect(() => {
    let id2 = 0;
    const id1 = requestAnimationFrame(() => {
      id2 = requestAnimationFrame(() =>
        picker.current?.setAttribute("data-ready", ""),
      );
    });
    return () => {
      cancelAnimationFrame(id1);
      cancelAnimationFrame(id2);
    };
  }, []);

  // Selection persists across reload via ?round= and ?v=
  useEffect(() => {
    if (!round) return;
    const url = new URL(window.location.href);
    url.searchParams.set("round", round.id);
    url.searchParams.set("v", String(current + 1));
    window.history.replaceState(null, "", url);
  }, [current, round]);

  useEffect(() => {
    const count = variants.length;
    function onKey(e: KeyboardEvent) {
      const t = e.target as HTMLElement | null;
      if (t && (/^(INPUT|TEXTAREA|SELECT)$/.test(t.tagName) || t.isContentEditable))
        return;
      if (e.metaKey || e.ctrlKey || e.altKey) return;

      const num = parseInt(e.key, 10);
      if (num >= 1 && num <= count) setCurrent(num - 1);
      else if (e.key === "ArrowRight") setCurrent((c) => (c + 1) % count);
      else if (e.key === "ArrowLeft") setCurrent((c) => (c - 1 + count) % count);
      else if (e.key === "r" || e.key === "R") setEpoch((n) => n + 1);
    }
    document.addEventListener("keydown", onKey);
    return () => document.removeEventListener("keydown", onKey);
  }, [variants.length]);

  if (!round || variants.length === 0) {
    return (
      <p className="p-8 text-sm text-gray-1000">
        No prototype rounds registered. Add one in registry.ts.
      </p>
    );
  }

  const active = variants[current] ?? variants[0];
  const Active = active.component;
  // Replay only makes sense if at least one variant has motion to re-trigger.
  const hasReplay = variants.some((v) => v.animated !== false);

  return (
    <>
      <style>{CSS}</style>
      {active.css ? <style>{active.css}</style> : null}

      {/* Switching re-mounts the variant so entrance animations re-run. */}
      <div key={`${round.id}-${current}-${epoch}`}>
        <Active rows={rows} />
      </div>

      {ROUNDS.length > 1 ? (
        <nav className="proto-rounds" aria-label="Prototype rounds">
          {ROUNDS.map((r) => (
            <button
              key={r.id}
              type="button"
              title={r.title}
              data-active={r.id === round.id ? "" : undefined}
              aria-current={r.id === round.id ? "true" : undefined}
              onClick={() => {
                setRoundId(r.id);
                setCurrent(0);
                setEpoch((n) => n + 1);
              }}
            >
              {r.id}
            </button>
          ))}
        </nav>
      ) : null}

      <nav
        ref={picker}
        className="proto-picker"
        data-position={active.pickerPosition}
        aria-label="Prototype variants"
      >
        <span
          ref={highlight}
          className="proto-picker-highlight"
          aria-hidden="true"
        />
        {variants.map((v, i) => (
          <button
            key={v.name}
            ref={(el) => {
              items.current[i] = el;
            }}
            type="button"
            className="proto-picker-item"
            data-active={i === current ? "" : undefined}
            aria-current={i === current ? "true" : undefined}
            onClick={() => setCurrent(i)}
          >
            {v.name}
          </button>
        ))}
        {hasReplay ? (
          <>
            <span className="proto-picker-divider" aria-hidden="true" />
            <button
              type="button"
              className="proto-picker-item proto-picker-replay"
              aria-label="Replay animation (R)"
              onClick={() => setEpoch((n) => n + 1)}
            >
              ↻
            </button>
          </>
        ) : null}
      </nav>
    </>
  );
}

const CSS = `
/* ---- variant motion (transform/opacity only, strong ease-out) ---- */
@keyframes proto-rise { from { opacity: 0; transform: translateY(8px); } to { opacity: 1; transform: none; } }
@keyframes proto-fade { from { opacity: 0; } to { opacity: 1; } }
@keyframes proto-ticker { from { transform: translateX(0); } to { transform: translateX(-50%); } }

.proto-rise { animation: proto-rise 260ms cubic-bezier(0.23, 1, 0.32, 1) both; animation-delay: calc(var(--i, 0) * 45ms); }
.proto-fade { animation: proto-fade 160ms ease-out both; }
.proto-ticker { animation: proto-ticker var(--dur, 60s) linear infinite; }
.proto-ticker[data-reverse] { animation-direction: reverse; }
.proto-ticker-wrap:hover .proto-ticker { animation-play-state: paused; }
.proto-stack-card {
  transform-origin: 50% 0;
  transition: transform 260ms cubic-bezier(0.23, 1, 0.32, 1), opacity 260ms ease-out;
  will-change: transform;
}
@media (prefers-reduced-motion: reduce) {
  .proto-rise, .proto-fade, .proto-ticker { animation: none; }
  .proto-stack-card { transition: none; }
}

/* ---- round switcher (separate from the picker) ---- */
.proto-rounds {
  position: fixed;
  top: 16px;
  left: 16px;
  z-index: 2147483647;
  display: flex;
  gap: 2px;
  padding: 3px;
  border-radius: 999px;
  background: rgba(10, 10, 10, 0.82);
  -webkit-backdrop-filter: blur(12px) saturate(1.4);
  backdrop-filter: blur(12px) saturate(1.4);
  box-shadow: 0 0 0 1px rgba(255, 255, 255, 0.08) inset, 0 4px 12px rgba(0, 0, 0, 0.18);
  font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
  font-size: 11px;
  line-height: 1;
}
.proto-rounds button {
  height: 24px;
  padding: 0 10px;
  border: 0;
  border-radius: 999px;
  background: transparent;
  color: rgba(255, 255, 255, 0.55);
  font: inherit;
  cursor: pointer;
  transition: color 150ms ease-out, background-color 150ms ease-out, transform 150ms ease-out;
}
.proto-rounds button:hover { color: rgba(255, 255, 255, 0.85); }
.proto-rounds button:active { transform: scale(0.97); }
.proto-rounds button[data-active] { color: #fff; background: rgba(255, 255, 255, 0.12); }
.proto-rounds button:focus-visible { outline: 2px solid rgba(255, 255, 255, 0.4); outline-offset: 2px; }

/* ---- picker: verbatim from PICKER.md ---- */
.proto-picker {
  position: fixed;
  bottom: 24px;
  left: 50%;
  transform: translateX(-50%);
  z-index: 2147483647;
  display: flex;
  align-items: center;
  gap: 2px;
  padding: 4px;
  border-radius: 999px;
  background: rgba(10, 10, 10, 0.82);
  -webkit-backdrop-filter: blur(12px) saturate(1.4);
  backdrop-filter: blur(12px) saturate(1.4);
  box-shadow:
    0 0 0 1px rgba(255, 255, 255, 0.08) inset,
    0 8px 24px rgba(0, 0, 0, 0.24),
    0 2px 6px rgba(0, 0, 0, 0.12);
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  font-size: 13px;
  line-height: 1;
  -webkit-font-smoothing: antialiased;
  user-select: none;
  -webkit-user-select: none;
}
.proto-picker-highlight {
  position: absolute;
  top: 4px;
  left: 0;
  height: 28px;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.12);
  will-change: transform;
}
.proto-picker[data-ready] .proto-picker-highlight {
  transition:
    transform 250ms cubic-bezier(0.23, 1, 0.32, 1),
    width 250ms cubic-bezier(0.23, 1, 0.32, 1);
}
@media (prefers-reduced-motion: reduce) {
  .proto-picker[data-ready] .proto-picker-highlight { transition: none; }
}
.proto-picker-item {
  position: relative;
  display: flex;
  align-items: center;
  height: 28px;
  padding: 0 12px;
  border: 0;
  border-radius: 999px;
  background: transparent;
  color: rgba(255, 255, 255, 0.55);
  font: inherit;
  cursor: pointer;
  transition: color 150ms ease-out;
}
.proto-picker-item:hover { color: rgba(255, 255, 255, 0.85); }
.proto-picker-item:active { transform: scale(0.97); }
.proto-picker-item:focus-visible { outline: 2px solid rgba(255, 255, 255, 0.4); outline-offset: 2px; }
.proto-picker-item[data-active] { color: #fff; }
.proto-picker-divider { width: 1px; height: 16px; margin: 0 4px; background: rgba(255, 255, 255, 0.12); }
.proto-picker-replay { padding: 0 10px; font-size: 14px; }
.proto-picker[data-position="top"] { bottom: auto; top: 24px; }
`;